-- 在 Supabase SQL Editor 一次性执行
create table if not exists public.cr_data (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.cr_data enable row level security;
drop policy if exists cr_data_authenticated on public.cr_data;
create policy cr_data_authenticated on public.cr_data
  for all to authenticated using (true) with check (true);

